// PreToolUse playbook — backend pre-check before tool runs.
// PRIMARY defense is Vrstva 1 local regex hooks (.claude/hooks/aisha-advise-*).
// This playbook handles cases that need DB context (e.g. file path matches
// a published rule binding for the active story).
//
// MVP: derive a soft compliance hint from path heuristics. Future: query
// expert_rule_subscriptions JOIN story_rulesets for story-scoped pattern
// matches.
const body = $input.first().json.body || $input.first().json;
if (body.event !== 'pre_tool') {
  throw new Error(`WF_DIRIGENT_COMPLIANCE_PRE_CHECK expects event=pre_tool, got ${body.event}`);
}
const toolInput = body.tool_input || {};
const filePath = String(toolInput.file_path || '');
const command = String(toolInput.command || '');

const hints = [];
// Path-based hints (mirror feedback_fix_at_source_of_truth.md)
if (/^aisha\/db\/migrations\//.test(filePath) && !/^.{0,200}archive/.test(filePath)) {
  hints.push('Migrace v aisha/db/migrations/: ujisti se, že paired SoT pair v aisha/db/sql/ je v sync (gate enforces).');
}
if (/baseline\.json$|baseline\.sql$/.test(filePath)) {
  hints.push('Baseline file je AUTO-GENERATED — needitovat ručně, opravit at source-of-truth a regenerovat.');
}
if (/\.aisha\//.test(filePath) && !/dirigent\.template\.json|static-defense-payload\.json/.test(filePath)) {
  hints.push('.aisha/ je generated territory (per feedback_aisha_dir_is_generated.md) — opravit producer, ne file in place.');
}
if (/aisha-branding\.baseline\.json/.test(filePath)) {
  hints.push('aisha-branding.baseline.json je gate — fix code, nikoliv baseline (feedback_no_workarounds_rewrite_dont_remove.md).');
}

const advisory = hints.length ? `🛡️ AISHA Pre-Check:\n- ${hints.join('\n- ')}` : '';
return [{
  json: {
    advisory,
    decision: 'allow',
    _audit: { event: 'pre_tool', story_id: body.story_id, session_id: body.session_id, file_path: filePath, command: command.slice(0,80), hint_count: hints.length }
  }
}];
